'use client';

import { useEffect } from 'react';

declare global {
  interface Window {
    Calendly?: {
      initInlineWidget: (options: {
        url: string;
        parentElement: HTMLElement;
        prefill?: {
          name?: string;
          email?: string;
          customAnswers?: Record<string, string>;
        };
        utm?: Record<string, string>;
      }) => void;
    };
  }
}

interface CalendlyWidgetProps {
  url: string; // e.g. 'https://calendly.com/your-name/30min'
  prefill?: {
    name?: string;
    email?: string;
  };
}

export function CalendlyWidget({ url, prefill }: CalendlyWidgetProps): JSX.Element {
  useEffect(() => {
    // Dynamically load the Calendly embed script
    const script = document.createElement('script');
    script.src = 'https://assets.calendly.com/assets/external/widget.js';
    script.async = true;
    document.head.appendChild(script);

    script.onload = () => {
      const container = document.getElementById('calendly-embed-container');
      if (container && window.Calendly) {
        window.Calendly.initInlineWidget({
          url,
          parentElement: container,
          prefill: prefill ?? {},
        });
      }
    };

    return () => {
      // Clean up script on unmount
      document.head.removeChild(script);
    };
  }, [url, prefill]);

  return (
    <div
      id="calendly-embed-container"
      style={{ minWidth: '320px', height: '700px' }}
    />
  );
}

// Usage:
// <CalendlyWidget
//   url="https://calendly.com/jane-doe/30min"
//   prefill={{ name: 'John Smith', email: 'john@example.com' }}
// />

const CALENDLY_API_BASE = 'https://api.calendly.com';

interface CalendlyUser {
  uri: string;
  name: string;
  email: string;
}

interface CalendlyEvent {
  uri: string;
  name: string;
  status: 'active' | 'canceled';
  start_time: string;
  end_time: string;
  event_type: string;
  invitees_counter: {
    total: number;
    active: number;
    limit: number;
  };
}

interface CalendlyEventsResponse {
  collection: CalendlyEvent[];
  pagination: {
    count: number;
    next_page: string | null;
    next_page_token: string | null;
  };
}

async function calendlyFetch<T>(path: string): Promise<T> {
  const response = await fetch(`${CALENDLY_API_BASE}${path}`, {
    headers: {
      Authorization: `Bearer ${process.env.CALENDLY_API_TOKEN}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`Calendly API error ${response.status}: ${response.statusText}`);
  }

  return response.json() as Promise<T>;
}

async function getScheduledEvents(): Promise<void> {
  // Step 1: Get the current user's URI (required for scoped queries)
  const me = await calendlyFetch<{ resource: CalendlyUser }>('/users/me');
  const userUri = me.resource.uri;

  console.log(`Fetching events for: ${me.resource.name} (${me.resource.email})`);

  // Step 2: Fetch upcoming active events
  const now = new Date().toISOString();
  const params = new URLSearchParams({
    user: userUri,
    status: 'active',
    min_start_time: now,
    count: '20',
    sort: 'start_time:asc',
  });

  const events = await calendlyFetch<CalendlyEventsResponse>(
    `/scheduled_events?${params}`
  );

  console.log(`Found ${events.collection.length} upcoming event(s)`);

  for (const event of events.collection) {
    // Extract UUID from the resource URI
    const eventId = event.uri.split('/').pop()!;
    console.log(`\nEvent ID: ${eventId}`);
    console.log(`  Name:   ${event.name}`);
    console.log(`  Start:  ${new Date(event.start_time).toLocaleString()}`);
    console.log(`  End:    ${new Date(event.end_time).toLocaleString()}`);
    console.log(`  Invitees: ${event.invitees_counter.active}/${event.invitees_counter.limit}`);
  }

  // Handle pagination
  if (events.pagination.next_page_token) {
    console.log(`\nMore events available. Next page token: ${events.pagination.next_page_token}`);
  }
}

getScheduledEvents().catch(console.error);
